OUT=ROOT/'assets/ui/production-v3/gameplay'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
read=lambda p:json.loads((ROOT/p).read_text(encoding='utf-8-sig'))
registry={}
for mpath,key in [('assets/tiles/manifest.json','tiles'),('assets/tiles/flowers/manifest.json','assets'),('assets/ui/gameplay/manifest.json','assets'),('assets/ui/common/manifest.json','assets'),('assets/ui/production-v3/gameplay/manifest.json','assets')]:
 for a in read(mpath)[key]:
  file=a['file']
  registry[a['id']]={'file':file,'sha256':sha(ROOT/file),'sourceManifest':mpath,'size':[a.get('width',448),a.get('height',640)],'nineSlice':a.get('nineSlice'),'resizePolicy':a.get('resizePolicy','uniform_scale_only')}
